param([string]$RepoRoot='C:\Users\aaron\Desktop\URAP',[string]$RunId='nps_action_bank_all_candidate_v4')
$root=Join-Path $RepoRoot 'artifacts\detached_nps_action_bank_all_candidate_v4';$pidFile=Join-Path $root ($RunId+'.pid');$metaFile=Join-Path $root ($RunId+'.meta.json');$pidValue=if(Test-Path $pidFile){[int](Get-Content $pidFile|Select-Object -First 1)}else{0};$p=if($pidValue){Get-Process -Id $pidValue -ErrorAction SilentlyContinue}else{$null};$m=if(Test-Path $metaFile){Get-Content $metaFile -Raw|ConvertFrom-Json}else{$null};$g=if($m-and(Test-Path $m.progress)){Get-Content $m.progress -Raw|ConvertFrom-Json}else{$null};$child=if($g-and$g.child_pid){Get-CimInstance Win32_Process -Filter "ProcessId=$($g.child_pid)" -ErrorAction SilentlyContinue}else{$null};$rt=if($g-and$g.child_pid){Get-CimInstance Win32_Process -Filter "ParentProcessId=$($g.child_pid)" -ErrorAction SilentlyContinue|Select-Object -First 1}else{$null};$last=if($m-and(Test-Path $m.stdout)){Get-Content $m.stdout -Tail 1}else{'none'};$gpu=if($m-and(Test-Path $m.stdout)){Get-Content $m.stdout -Tail 100|Select-String 'cuda_memory_allocated_mb'|Select-Object -Last 1}else{$null};"status: $(if($p){'RUNNING'}else{'NOT RUNNING'})";"done/total: $(if($g){$g.done.ToString()+'/'+$g.total}else{'0/3'})";"stage: $(if($g){$g.stage}else{'not_started'})";"pid: $pidValue";"start_time: $(if($p){$p.StartTime}else{if($m){$m.started}else{'unknown'}})";"child_pid: $(if($g){$g.child_pid}else{'none'})";"child_command: $(if($child){$child.CommandLine}else{'none'})";"runtime_pid: $(if($rt){$rt.ProcessId}else{'none'})";"last_output_timestamp: $(if($m-and(Test-Path $m.stdout)){(Get-Item $m.stdout).LastWriteTime}else{'none'})";"last_completed_unit: $last";"gpu_signal: $(if($gpu){$gpu.Line}else{'NO GPU SIGNAL YET'})";"stdout: $($m.stdout)";"stderr: $($m.stderr)";"progress: $($m.progress)"
